"""Maximum drawdown with its dates (RISK-05)."""

import math
from itertools import accumulate

from risk.types import Drawdown, Returns


def max_drawdown(returns: Returns) -> tuple[Drawdown, ...]:
    """Each ticker's deepest fall below its running peak, wealth starting at 1 on `base_date`.

    The first peak and trough win ties; with no fall, depth is 0 and both dates are `base_date`.
    """
    dates = (returns.base_date, *returns.dates)
    return tuple(
        _drawdown(ticker, dates, returns.values[ticker]) for ticker in returns.tickers
    )


def _drawdown(ticker: str, dates: tuple[str, ...], log_returns: tuple[float, ...]) -> Drawdown:
    """Walk log wealth, tracking the running peak and the deepest fall below it."""
    log_wealth = accumulate(log_returns, initial=0.0)
    peak, peak_i = 0.0, 0
    worst, worst_peak_i, worst_trough_i = 0.0, 0, 0
    for i, wealth in enumerate(log_wealth):
        if wealth > peak:
            peak, peak_i = wealth, i
        elif wealth - peak < worst:
            worst, worst_peak_i, worst_trough_i = wealth - peak, peak_i, i
    return Drawdown(
        ticker=ticker,
        depth=math.expm1(worst),
        peak_date=dates[worst_peak_i],
        trough_date=dates[worst_trough_i],
    )

